// Decide quem recebe follow-up hoje e monta a mensagem.
function parseDataBR(txt) {
  const partes = String(txt).trim().split('/');
  if (partes.length !== 3) return null;
  const [d, m, y] = partes.map(Number);
  return new Date(y, m - 1, d);
}

function reais(v) {
  const n = Number(String(v).replace(',', '.')) || 0;
  return n.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);
const LIMITE_POR_EXECUCAO = 10;

const saida = [];

for (const item of $input.all()) {
  const o = item.json;
  if (String(o.status || '').trim() !== 'enviado') continue;

  const enviado = parseDataBR(o.data_envio);
  if (!enviado) continue;
  const dias = Math.floor((hoje - enviado) / 86400000);

  const toqueAtual = String(o.ultimo_toque || '').trim();
  let toque = null;

  if (toqueAtual === '' && dias >= 2) {
    toque = 'follow1';
  } else if (toqueAtual === 'follow1' && dias >= 7) {
    toque = 'follow2';
  }
  if (!toque) continue;

  const primeiroNome = String(o.cliente || '').split(' ')[0];
  let mensagem;
  if (toque === 'follow1') {
    mensagem = `Oi, ${primeiroNome}! Aqui é o ${o.vendedor} da Móveis Premium 😊 Conseguiu dar uma olhada no orçamento do ${o.descricao}? Ficou alguma dúvida que eu possa esclarecer?`;
  } else {
    mensagem = `Oi, ${primeiroNome}! Passando para avisar que a condição do orçamento do ${o.descricao} (R$ ${reais(o.valor)}) vale até sexta. Quer que eu reserve para você?`;
  }

  saida.push({
    json: {
      row_number: o.row_number,
      cliente: o.cliente,
      para: String(o.telefone),
      mensagem,
      toque,
      dias,
      vendedor: o.vendedor,
      descricao: o.descricao,
    },
  });
}

return saida.slice(0, LIMITE_POR_EXECUCAO);
